'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var linspace = require( '@stdlib/array/linspace' );
var EPS = require( '@stdlib/constants/float32/eps' );
var log1pf = require( '@stdlib/math/base/special/log1pf' );
var absf = require( '@stdlib/math/base/special/absf' );
var powf = require( '@stdlib/math/base/special/powf' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var log1pmxf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( log1pmxf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof log1pmxf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if input is less than or equal to -1', opts, function test( t ) {
	var values = linspace( -1.0, -50.0, 100 );
	var i;
	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( isnanf( log1pmxf( values[ i ] ) ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes lnf(1+x) - x if |x| > 0.95', opts, function test( t ) {
	var expected;
	var values = linspace( 0.951, 100.0, 100 );
	var actual;
	var i;
	for ( i = 0; i < values.length; i++ ) {
		actual = log1pmxf( values[i] );
		expected = f32( lnf( f32( 1.0 + values[i] ) ) - f32( values[i] ) );
		t.strictEqual( actual, expected, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns -x*x/2 if |x| < FLOAT_EPS', opts, function test( t ) {
	var expected;
	var values = [ 0.0, EPS / 2.0 ];
	var actual;
	var i;
	for ( i = 0; i < values.length; i++ ) {
		actual = log1pmxf( values[i] );
		expected = f32( -powf( f32( values[i] ), 2 ) / 2.0 );
		t.strictEqual( actual, expected, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns a Taylor series expansion otherwise', opts, function test( t ) {
	var expected;
	var values;
	var actual;
	var delta;
	var tol;
	var i;

	values = linspace( 0.1, 0.95, 100 );
	for ( i = 0; i < values.length; i++ ) {
		actual = log1pmxf( values[ i ] );
		expected = f32( log1pf( f32( values[ i ] ) ) - f32( values[ i ] ) );
		if ( actual === expected ) {
			t.strictEqual( actual, expected, 'returns expected value' );
		} else {
			delta = absf( f32( actual - expected ) );
			tol = f32( 100.0 * EPS * absf( expected ) );
			t.ok( delta <= tol, 'within tolerance. x: '+values[ i ]+'. actual: '+actual+'. expected: '+expected+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});
